const problems = [];
const notes = [];
const now = Date.now();
const B = 'https://144.31.194.174.nip.io/webhook/';

// 1) кэш-вебхуки: отвечают + не устарели
const WH = [
  ['today-dashboard',  '?token=td_92Wl74Z7rw', 3],
  ['health-dashboard', '?token=hd_7Kx92mQr4T', 3],
  ['bioage-dashboard', '?token=ba_9Fw3nZp7Kd', 27],
  ['weekly-nutrients', '', 30],
  ['recipes', '', 30],
];
for (const [path, q, maxH] of WH) {
  try {
    const res = await this.helpers.httpRequest({ method: 'GET', url: B + path + q, timeout: 20000, json: true });
    if (res && res.error) { problems.push(path + ': error=' + res.error); continue; }
    const ua = res && (res.updated_at || res.computed_at);
    if (ua && /^\d{4}-\d{2}-\d{2}T\d/.test(String(ua))) {
      const ageH = (now - new Date(ua).getTime()) / 3600000;
      if (ageH > maxH) problems.push(path + ': кэш устарел на ' + Math.round(ageH) + 'ч (порог ' + maxH + 'ч)');
    } else {
      problems.push(path + ': ответ без метки времени (updated_at/computed_at)');
    }
  } catch (e) { problems.push(path + ': не отвечает (' + String(e.message).slice(0, 60) + ')'); }
}
// виджет-страница: живость
try {
  const html = await this.helpers.httpRequest({ method: 'GET', url: B + 'dashboard?token=79TytaFim5VByE', timeout: 20000 });
  if (!/<!DOCTYPE|<html/i.test(String(html))) problems.push('dashboard (виджет): не отдаёт HTML');
} catch (e) { problems.push('dashboard (виджет): не отвечает (' + String(e.message).slice(0, 60) + ')'); }

// 2) дыры в Daily_Trends и day_sum за последние 5 дней (без вчера).
// ВАЖНО: пустой ответ Sheets-ноды = сбой чтения (лимит квоты), а НЕ отсутствие данных —
// в этом случае проверку пропускаем с пометкой, ложную тревогу не поднимаем.
function d10(v){ return String(v==null?'':v).trim().slice(0,10); }
function isDate(x){ return /^\d{4}-\d{2}-\d{2}$/.test(x); }
const dtDates = $('Get Daily_Trends').all().map(i => d10(i.json['Дата'] || i.json['Date'])).filter(isDate);
const dsDates = $('Get day_sum').all().map(i => d10(i.json['Date'] || i.json['Дата'])).filter(isDate);
const dtSet = new Set(dtDates), dsSet = new Set(dsDates);
const days5 = [];
for (let k = 2; k <= 6; k++) days5.push(new Date(now + 10*3600000 - k*86400000).toISOString().slice(0, 10));

if (dtSet.size === 0) notes.push('Daily_Trends не прочитан (лимит Google Sheets?) — проверка дыр пропущена');
else { const m = days5.filter(d => !dtSet.has(d)); if (m.length) problems.push('Daily_Trends нет строк за: ' + m.join(', ') + ' (Garmin-пайплайн?)'); }

if (dsSet.size === 0) notes.push('day_sum не прочитан (лимит Google Sheets?) — проверка дыр пропущена');
else { const m = days5.filter(d => !dsSet.has(d)); if (m.length) problems.push('day_sum нет строк за: ' + m.join(', ') + ' (лог еды?)'); }

// 3) фикстуры safety-гейта — регрессия логики фильтра нагрузки
const LOAD_RX = /интенсив|интервал|бег|присед|штанг|отжим|планк|скручиван|ротац|растяж|йог|лфк|силов|берпи|подтяг/i;
const gateBlocks = (title, why, contra) => contra ? LOAD_RX.test(title + ' ' + why) : false;
const fx = [
  ['Растяжка с ротацией корпуса', 'снять напряжение', true,  true],
  ['Интервальный бег 3р/нед',     'vo2max',            true,  true],
  ['Убрать сахар после 20:00',    'глюкоза',           true,  false],
  ['Ходьба 30 мин',               'движение',          true,  false],
  ['Силовая на всё тело',         'мышцы',             false, false],
];
const fxFail = fx.filter(([t, w, c, exp]) => gateBlocks(t, w, c) !== exp);
if (fxFail.length) problems.push('ФИКСТУРА ГЕЙТА СЛОМАНА: ' + fxFail.map(f => f[0]).join('; '));

// 4) итог
const ts = new Date(now + 10*3600000).toISOString().slice(0, 16).replace('T', ' ');
let msg;
if (problems.length) {
  msg = '\u26a0\ufe0f <b>Система: проблемы (' + ts + ' ВЛ)</b>\n\n\u2022 ' + problems.join('\n\u2022 ');
  if (notes.length) msg += '\n\n<i>' + notes.join('; ') + '</i>';
} else if (notes.length) {
  msg = '\u2705 Система в норме (' + ts + ' ВЛ), но: ' + notes.join('; ') + '.';
} else {
  msg = '\u2705 Система в норме (' + ts + ' ВЛ). 6 вебхуков живы, кэши свежие, Daily_Trends/day_sum без дыр за 5 дней, фикстуры гейта ок.';
}
return [{ json: { message: msg, has_problems: problems.length > 0, problems, notes } }];

